local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Read-only public native observations. No frames, timers, outputs or actions.
local _, ns = ...
local Adapter = {}
local ROUNDTRIP_TOLERANCE = 0.01 -- yards; numerical conversion error only

local function Public(api,value)
    if type(api.issecretvalue)=='function' then
        local ok,secret=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](api.issecretvalue,value)
        if not ok or secret~=false then return end
    end
    return value
end--[[APR_DIAG]]; Public = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:11:Public#1", Public)--[[/APR_DIAG]]

local function Call(api,fn,...)
    if type(fn)~='function' then return end
    local ok,a,b,c,d=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](fn,...)
    if not ok then return end
    return Public(api,a),Public(api,b),Public(api,c),Public(api,d)
end--[[APR_DIAG]]; Call = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:19:Call#2", Call)--[[/APR_DIAG]]

local function Number(value)
    if type(value)=='number' and value==value and value>-math.huge and value<math.huge then return value end
end--[[APR_DIAG]]; Number = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:26:Number#3", Number)--[[/APR_DIAG]]

local function ID(value,minimum)
    value=Number(value)
    if value and value>=minimum and value<=9007199254740991 and value%1==0 then return value end
end--[[APR_DIAG]]; ID = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:30:ID#4", ID)--[[/APR_DIAG]]

local function Identity(api,value)
    value=Public(api,value)
    if type(value)=='string' and value~='' then return value end
    return ID(value,0)
end--[[APR_DIAG]]; Identity = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:35:Identity#5", Identity)--[[/APR_DIAG]]

-- Primary PlayerScript API in Forever 1.60.1 and Retail 12.1.5. In particular,
-- IsLoggedIn and valid coordinates are not substituted for in-world readiness.
function Adapter.Ready(api)
    api=api or _G
    local ready=Call(api,api.IsPlayerInWorld)
    if type(ready)=='boolean' then return ready end
end--[[APR_DIAG]]; Adapter.Ready = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:43:Adapter.Ready#6", Adapter.Ready)--[[/APR_DIAG]]

function Adapter.Observe(api,sequence,worldLoading,identity)
    api=api or _G
    local state=worldLoading==true and 'loading' or (worldLoading==false and 'ready' or 'unknown')
    local result={sequence=sequence,worldState=state}
    if state~='ready' then return result end
    local x,y,z,world=Call(api,api.UnitPosition,'player')
    result.x,result.y,result.z,result.world=Number(x),Number(y),Number(z),ID(world,0)
    local maps=Public(api,api.C_Map)
    if type(maps)=='table' then result.uiMapID=ID(Call(api,maps.GetBestMapForUnit,'player'),1) end
    if type(identity)=='table' then
        for _,key in ipairs({'space','floor','phase'}) do result[key]=Identity(api,identity[key]) end
    end
    return result
end--[[APR_DIAG]]; Adapter.Observe = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:49:Adapter.Observe#7", Adapter.Observe)--[[/APR_DIAG]]

local function Vector(api,value)
    value=Public(api,value)
    if type(value)~='table' then return end
    -- Native vector2 is a Vector2DMixin table; accesses stay inside pcall in case
    -- a provider returns an opaque or restricted value instead.
    local ok,x,y=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](--[[APR_DIAG]]APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:69:callback#9", --[[/APR_DIAG]]function()return value.x,value.y end--[[APR_DIAG]])--[[/APR_DIAG]])
    if not ok then return end
    x,y=Number(Public(api,x)),Number(Public(api,y))
    if x and y then return x,y end
end--[[APR_DIAG]]; Vector = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:64:Vector#8", Vector)--[[/APR_DIAG]]

-- Explicit map projection of an already proven world identity. It is a 2D API,
-- not proof of a floor/phase, a traversable line, a node membership or arrival.
-- The host must Match required identities before publishing this map point.
function Adapter.Project(api,position,uiMapID)
    api=api or _G
    uiMapID=ID(Public(api,uiMapID),1)
    if not uiMapID then return nil,'map_missing' end
    if type(position)~='table' then return nil,'position_missing' end
    local world=ID(Public(api,position.world),0)
    local x,y=Number(Public(api,position.x)),Number(Public(api,position.y))
    if not world or not x or not y then return nil,'position_missing' end
    local maps=Public(api,api.C_Map)
    if type(maps)~='table' then return nil,'projection_unavailable' end
    local vector=Call(api,api.CreateVector2D,x,y)
    if not vector then return nil,'projection_unavailable' end
    local map,point=Call(api,maps.GetMapPosFromWorldPos,world,vector,uiMapID)
    if map==nil or point==nil then return nil,'projection_unavailable' end
    map=ID(map,1)
    local mx,my=Vector(api,point)
    if map~=uiMapID or not mx or not my or mx<0 or mx>1 or my<0 or my>1 then return nil,'projection_unreliable' end
    local reverse=Call(api,api.CreateVector2D,mx,my)
    if not reverse then return nil,'projection_unavailable' end
    local reverseWorld,reversePoint=Call(api,maps.GetWorldPosFromMapPos,map,reverse)
    local rx,ry=Vector(api,reversePoint)
    if reverseWorld~=world or not rx or not ry
        or math.abs(rx-x)>ROUNDTRIP_TOLERANCE or math.abs(ry-y)>ROUNDTRIP_TOLERANCE then
        return nil,'projection_unreliable'
    end
    return {mapID=map,x=mx,y=my}
end--[[APR_DIAG]]; Adapter.Project = APRTrace("APR-Core/features/navigation/NavigationV2Position.lua:78:Adapter.Project#10", Adapter.Project)--[[/APR_DIAG]]

ns.NavigationV2Position=Adapter
return Adapter
